(async () => {
 const main=document.getElementById('main'),data=window.SCHOOL_DATA,params=new URLSearchParams(location.search),lesson=data.lessons?.find(l=>l.id===params.get('lesson')),id=lesson?.book||params.get('book');
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 if(!data.books?.[id]){main.innerHTML='<div class="not-found"><h1>選一段故事，開始閱讀</h1><p>從課程、教案或學期成果出發。</p><a class="button" href="resources.html">找資料</a></div>';return;}
 let book;
 try{const response=await fetch('books/'+encodeURIComponent(id)+'.json');if(!response.ok)throw new Error('讀取失敗');book=await response.json();}catch{main.innerHTML='<div class="not-found"><h1>這頁暫時打不開</h1><p>請重新整理頁面，再試一次。</p><a class="button" href="resources.html">返回資料服務站</a></div>';return;}
 const displayTitle=lesson?lesson.title+'｜教案':book.title;document.title=displayTitle+'｜Salimpo 山海閱讀室';const pageMode=book.format==='pages',total=pageMode?book.count:book.chapters.length,first=lesson?.start||1,last=lesson?.end||total,tocChapters=lesson?[{title:lesson.title,page:first}]:book.chapters;let current=Math.min(last,Math.max(first,Number(params.get('page')||params.get('chapter')||first)));if(!Number.isInteger(current))current=first;
 const parent=id.startsWith('visit115')||id==='plan114Approved'?['visits.html','訪視評鑑會客室']:['resources.html','資料服務站'];
 document.querySelector(`.main-nav a[href="${parent[0]}"]`)?.setAttribute('aria-current','page');
 main.innerHTML=`<header class="reader-title"><div class="breadcrumb"><a href="index.html">首頁</a><span>/</span><a href="${parent[0]}">${parent[1]}</a><span>/</span><span>山海閱讀室</span></div><h1>${esc(displayTitle)}</h1><p>${lesson?`${last-first+1} 頁本主題教案`:pageMode?`${total} 頁圖文內容`:`${total} 個章節`} · 選一個章節，或往下一頁繼續讀。${lesson?` <a class="text-link" href="lessons.html?lesson=${esc(lesson.id)}">返回教案主題 →</a>`:''}</p></header><div class="reader-layout"><aside class="reader-toc"><h2>這段旅程的地圖</h2><nav>${tocChapters.map((c,i)=>`<button type="button" data-location="${pageMode?c.page:i+1}">${esc(c.title)}</button>`).join('')}</nav><div class="reader-search"><label for="book-search">${lesson?'搜尋這個教案':id==='plan115'?'找課程架構主題':book.textMode==='highlights'?'找主題與章節':'搜尋這本內容'}</label><input id="book-search" type="search" placeholder="輸入主題或關鍵字"><div id="book-search-results" aria-live="polite"></div></div></aside><section><div class="reader-tools"><button type="button" class="pill" id="reader-prev">← 上一${pageMode?'頁':'章'}</button><label for="reader-jump">第 <input id="reader-jump" type="number" min="${lesson?1:first}" max="${lesson?last-first+1:last}" value="${lesson?current-first+1:current}"> ${pageMode?'頁':'章'}</label><button type="button" class="pill" id="reader-next">下一${pageMode?'頁':'章'} →</button><span class="reader-progress" id="reader-progress" aria-live="polite"></span></div><div class="reader-content" id="reader-content"></div></section></div>`;
 const content=main.querySelector('#reader-content'),jump=main.querySelector('#reader-jump');
 const photo=(id)=>{const a=data.assets[id];return a?`<button type="button" class="photo-open" data-photo="${esc(id)}" data-caption="${esc(book.title)}"><img src="${esc(a.src)}" alt="${esc(book.title)}的圖文紀錄" loading="lazy" decoding="async"><span>放大觀看 ↗</span></button>`:'';};
 function blocks(items){return items.map(b=>b.kind==='table'?`<div class="doc-table-scroll"><table class="doc-table"><tbody>${b.rows.map(row=>`<tr>${row.map(cell=>`<td>${blocks(cell)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:`${b.text?`<${b.heading?'h3':'p'} class="${b.heading?'doc-heading':'doc-paragraph'}${b.lang==='ami'?' doc-ami':''}"${b.lang?` lang="${esc(b.lang)}"`:""}>${esc(b.text)}</${b.heading?'h3':'p'}>`:''}${b.images?.length?`<div class="doc-pictures">${b.images.map(photo).join('')}</div>`:''}`).join('');}
 function draw(){
  jump.value=lesson?current-first+1:current;main.querySelector('#reader-progress').textContent=lesson?(current-first+1)+' / '+(last-first+1)+' 頁':current+' / '+total;main.querySelector('#reader-prev').disabled=current===first;main.querySelector('#reader-next').disabled=current===last;
  if(pageMode){const page=book.pages[current-1];content.innerHTML=`${page.note?`<div class="reader-map-note"><p>${esc(page.note)}</p><a class="text-link" href="${esc(page.mapLink.url)}">${esc(page.mapLink.label)}</a></div>`:''}<img class="reader-page" src="${esc(page.src)}" alt="${esc(displayTitle)}第${lesson?current-first+1:current}頁" fetchpriority="high">${(id==='plan115'||book.textMode==='highlights')&&!page.text?'':`<details class="reader-text-toggle"><summary>${(id==='plan115'||book.textMode==='highlights')?'閱讀本頁重點':'閱讀本頁文字'}</summary><pre>${esc(page.text||'本頁以圖像呈現。')}</pre></details>`}`;}
  else {const chapter=book.chapters[current-1];content.innerHTML=`<article class="reader-chapter"><h2>${esc(chapter.title)}</h2>${blocks(chapter.blocks)}</article>`;}
  let active=pageMode?[...tocChapters].reverse().find(c=>c.page<=current)?.page:current;main.querySelectorAll('[data-location]').forEach(b=>b.setAttribute('aria-current',String(Number(b.dataset.location)===active)));
  const url=new URL(location.href);url.searchParams.set(pageMode?'page':'chapter',current);history.replaceState(null,'',url);
 }
 function go(n){if(Number.isInteger(n)&&n>=first&&n<=last){current=n;draw();content.scrollIntoView({block:'start',behavior:'auto'});}}
 main.querySelector('#reader-prev').onclick=()=>go(current-1);main.querySelector('#reader-next').onclick=()=>go(current+1);const jumpToPage=()=>go(Number(jump.value)+(lesson?first-1:0));jump.onchange=jumpToPage;jump.onkeydown=e=>{if(e.key==='Enter')jumpToPage();};main.querySelectorAll('[data-location]').forEach(b=>b.onclick=()=>go(Number(b.dataset.location)));
 const flatten=items=>items.map(b=>b.kind==='table'?b.rows.map(r=>r.map(flatten).join(' ')).join(' '):b.text||'').join(' ');
 main.querySelector('#book-search').addEventListener('input',e=>{const q=e.target.value.trim().toLocaleLowerCase();const target=main.querySelector('#book-search-results');if(q.length<2){target.innerHTML='';return;}const records=pageMode?book.pages.map((p,i)=>({text:p.text,n:i+1,title:'第 '+(lesson?i+2-first:i+1)+' 頁'})):tocChapters.map((c,i)=>({text:flatten(c.blocks),n:i+1,title:c.title}));const hits=records.filter(r=>r.n>=first&&r.n<=last&&r.text.toLocaleLowerCase().includes(q)).slice(0,20);target.innerHTML=hits.length?hits.map(r=>`<button type="button" class="reader-search-result" data-result="${r.n}">${esc(r.title)}</button>`).join(''):'<p class="source-note">換個詞，再找找看。</p>';target.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>go(Number(b.dataset.result)));});
 draw();
})();
